import{_ as r,o as e,c as a,a2 as d}from"./chunks/framework.Ca9F9Y59.js";const n="/k3gdb/assets/02CPU-hart%E6%98%A0%E5%B0%84%E5%88%9D%E5%A7%8B%E5%8C%96.BKgCyHsR.png",o="/k3gdb/assets/05%E4%BC%98%E5%8C%96%E5%90%8E%E6%B6%88%E8%80%97.1hzDrOVx.png",s="/k3gdb/assets/04%E6%96%87%E4%BB%B6%E5%85%B3%E9%97%AD%E9%98%B6%E6%AE%B5%E8%80%97%E6%97%B6.BjVHmLYW.png",S=JSON.parse('{"title":"K3 + StarryOS 启动与运行缓慢问题排查","description":"","frontmatter":{},"headers":[],"relativePath":"2026-10-08-StarryOS启动缓慢问题.md","filePath":"2026-10-08-StarryOS启动缓慢问题.md"}'),l={name:"2026-10-08-StarryOS启动缓慢问题.md"};function h(i,t,g,p,c,y){return e(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="k3-starryos-启动与运行缓慢问题排查" tabindex="-1">K3 + StarryOS 启动与运行缓慢问题排查 <a class="header-anchor" href="#k3-starryos-启动与运行缓慢问题排查" aria-label="Permalink to &quot;K3 + StarryOS 启动与运行缓慢问题排查&quot;">​</a></h1><p>本周继续调查了 <strong>K3 COM260 真板上 StarryOS 启动及运行缓慢的问题</strong>。虽然目前已经打通了 StarryOS、J-Link、OpenOCD、GDB 和 ARD 的基本调试链路，但从系统启动到进入 Shell 仍然需要几分钟，部分简单命令执行也比较慢，影响了日常调试效率。</p><p>这次主要完成了三项工作：<strong>验证日志输出对启动性能的影响、定位并优化 CPU→hart 映射中的重复设备树查询，以及初步排查文件系统相关耗时。</strong></p><h2 id="_1-首先验证内核日志太多导致启动缓慢" tabindex="-1">1. 首先验证内核日志太多导致启动缓慢 <a class="header-anchor" href="#_1-首先验证内核日志太多导致启动缓慢" aria-label="Permalink to &quot;1. 首先验证内核日志太多导致启动缓慢&quot;">​</a></h2><p>一开始，我们怀疑 StarryOS 在启动过程中输出了大量内核日志，串口打印可能占用了较多时间。</p><p>分别构建了两组 A/B StarryOS 镜像：</p><ul><li><strong>Info 组</strong>：保留普通 Info 级别的内核日志。</li><li><strong>Warn 组</strong>：过滤 Info 日志，仅保留 Warn 及更高等级的日志。</li></ul><p>两组镜像使用相同的启动链及 CPU→hart 映射缓存实现，仅调整内核日志等级。在 K3 真板上共完成了 <strong>4 次有效启动测试，Info 和 Warn 各 2 次</strong>。</p><table tabindex="0"><thead><tr><th>测试</th><th>日志等级</th><th style="text-align:right;">Welcome → Shell</th><th style="text-align:right;">UART 输出量</th></tr></thead><tbody><tr><td>A1</td><td>Info</td><td style="text-align:right;">263.22 秒</td><td style="text-align:right;">84,920 B</td></tr><tr><td>B1</td><td>Warn</td><td style="text-align:right;">260.19 秒</td><td style="text-align:right;">26,249 B</td></tr><tr><td>B2</td><td>Warn</td><td style="text-align:right;">260.24 秒</td><td style="text-align:right;">26,252 B</td></tr><tr><td>A2</td><td>Info</td><td style="text-align:right;">263.41 秒</td><td style="text-align:right;">84,949 B</td></tr></tbody></table><p>从结果可以看到，<strong>Warn 模式下 UART 输出量减少了约 69%，但 Welcome 到 Shell 的平均耗时只减少了约 3.1 秒</strong>。四次有效测试都能正常进入 Shell，两组各自的测试结果也比较接近。</p><p>这说明，减少普通内核日志确实能降低串口输出量，但无法消除系统长达四分多钟的启动等待。现有结果不支持将启动缓慢主要归因于 Info 日志打印。</p><p>因此后续把重点转向了实际的内核执行路径。</p><h2 id="_2-进一步定位-cpu→hart-映射反复查询设备树" tabindex="-1">2. 进一步定位：CPU→hart 映射反复查询设备树 <a class="header-anchor" href="#_2-进一步定位-cpu→hart-映射反复查询设备树" aria-label="Permalink to &quot;2. 进一步定位：CPU→hart 映射反复查询设备树&quot;">​</a></h2><p>在排查系统调用和进程创建过程时，发现 K3 多核处理器发送 IPI（处理器间中断）时，需要将逻辑 CPU 编号转换为硬件 hart ID。</p><p>原有实现中，这个转换过程会反复遍历设备树，查找逻辑 CPU 与 hart ID 的对应关系。</p><p>问题在于，<strong>这份映射关系在启动阶段就已经能确定，但运行时仍然重复查询</strong>。当操作涉及多个 CPU，或者系统频繁执行相关路径时，就会产生额外开销。</p><p>通过分段计时发现，在一次涉及 15 个目标 CPU 的操作中，CPU 映射查询累计耗时约 <strong>307.40 ms</strong>。</p><p>针对这一问题采用了比较直接的优化方案：<strong>系统启动时建立 CPU→hart 映射缓存表，后续发送 IPI 时直接查表，不再反复遍历设备树。</strong></p><p>这一修改不改变 CPU 与 hart 的实际对应关系，只改变映射信息的获取方式。</p><p><img src="'+n+'" alt="启动时 CPU-hart 映射缓存初始化日志"></p><p>随后，在 K3 真板上进行了优化前后测试：</p><table tabindex="0"><thead><tr><th>测试指标</th><th style="text-align:right;">优化前</th><th style="text-align:right;">优化后</th></tr></thead><tbody><tr><td>CPU 映射累计耗时</td><td style="text-align:right;">307.40 ms</td><td style="text-align:right;">0.00146 ms</td></tr><tr><td>完整进程创建（clone）阶段</td><td style="text-align:right;">624.22 ms</td><td style="text-align:right;">0.332 ms</td></tr><tr><td><code>/bin/true</code> 整体内部观测耗时</td><td style="text-align:right;">1789.60 ms</td><td style="text-align:right;">1135.82 ms</td></tr></tbody></table><p>测试程序均正常完成，相关多核响应检查通过。</p><p>结果说明，<strong>重复遍历设备树确实是此前内核执行路径中的一个明显性能问题，而启动时缓存 CPU→hart 映射能够有效消除这部分重复查询开销。</strong></p><p>在此前完整启动的阶段性对照中，Welcome 到 root Shell 的等待时间也观察到了约 <strong>43 秒的改善</strong>。</p><p><img src="'+o+'" alt="优化后消耗"></p><h2 id="_3-优化后仍然需要四分多钟" tabindex="-1">3. 优化后仍然需要四分多钟 <a class="header-anchor" href="#_3-优化后仍然需要四分多钟" aria-label="Permalink to &quot;3. 优化后仍然需要四分多钟&quot;">​</a></h2><p>虽然 CPU→hart 映射问题已经得到改善，但后续的 Info/Warn 实验也证明，优化后的 StarryOS 从 Welcome 到 Shell 仍需要约 <strong>260～263 秒</strong>。</p><p>因此继续观察了用户态初始化流程，其中几个比较明显的耗时阶段是：</p><table tabindex="0"><thead><tr><th>阶段</th><th style="text-align:right;">典型耗时</th></tr></thead><tbody><tr><td><code>env</code></td><td style="text-align:right;">约 34 秒</td></tr><tr><td><code>touch</code></td><td style="text-align:right;">约 5～6 秒</td></tr><tr><td><code>cat</code></td><td style="text-align:right;">约 5 秒</td></tr></tbody></table><p>此外，登录 Shell 的初始化过程中还会反复执行 <code>grep</code>、<code>head</code>、<code>dash</code> 等程序，这些操作累计消耗了较多时间。</p><p>继续检查相关执行路径时，发现，<strong>部分用户态程序在文件关闭阶段存在较明显的开销</strong>，涉及 ext4 文件系统元数据处理及块设备读写；UFS 相关读取路径也存在一定的累计耗时。</p><p>不过，目前的证据还不能直接说明这些耗时全部由 UFS 硬件读写造成。文件操作过程中还涉及系统调用、进程调度、缓存管理以及文件系统内部逻辑，需要进一步区分。</p><p>因此，现阶段只能将文件系统及存储 I/O 视为值得继续排查的方向，<strong>尚未定位最终根因</strong>。</p><p><img src="'+s+'" alt="文件阶段耗时"></p><h2 id="_4-本周结果与下一步计划" tabindex="-1">4. 本周结果与下一步计划 <a class="header-anchor" href="#_4-本周结果与下一步计划" aria-label="Permalink to &quot;4. 本周结果与下一步计划&quot;">​</a></h2><p>本周主要完成了两个问题的验证。</p><p>首先，通过四次真实 K3 启动实验，确认了普通内核 Info 日志虽然明显增加串口输出量，但并不是数分钟启动延迟的主要原因。</p><p>其次，通过源码分析、分段计时和真板 A/B 测试，定位并解决了 CPU→hart 映射中反复遍历设备树的问题。优化后，映射查询开销明显下降，相关进程创建路径也得到改善，完整启动时间观察到约 43 秒的阶段性缩短。</p><p>与此同时，<strong>系统仍然存在较大的用户态程序执行及文件操作开销</strong>，特别是重复执行外部命令、文件关闭、ext4 元数据处理和 UFS 访问等路径，值得后续继续分析。在此基础上，启用 ARD 异步追踪与相关断点后，又观察到了额外约 30 秒的执行延迟。后续应该追踪断点处理与低速 JTAG 通信的累计开销。</p>',40)])])}const x=r(l,[["render",h]]);export{S as __pageData,x as default};
